window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"FRqig0GwFT0","speaker":"Samuel Ntsokoane Matekane","role":"Prime Minister","country":"Lesotho","region":"Africa","url":"https://www.youtube.com/watch?v=FRqig0GwFT0","date":"20260925","title":"🇱🇸 Lesotho - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1062,"words":1725,"counts":{"claims":24,"promises":1,"attacks":0},"topics":[{"topic":"UNGA","share":0.1308,"seconds":139},{"topic":"Lesotho security","share":0.0847,"seconds":90},{"topic":"Lesotho energy","share":0.0811,"seconds":86},{"topic":"Conflict zones","share":0.0731,"seconds":78},{"topic":"Finance","share":0.071,"seconds":75},{"topic":"Technology","share":0.0697,"seconds":74},{"topic":"Migration","share":0.0681,"seconds":72},{"topic":"UN reform","share":0.0648,"seconds":69},{"topic":"Sanctions","share":0.0639,"seconds":68},{"topic":"UN leadership","share":0.0607,"seconds":64},{"topic":"Lesotho health","share":0.0599,"seconds":64},{"topic":"Lesotho climate","share":0.0583,"seconds":62},{"topic":"Lesotho economy","share":0.0572,"seconds":61},{"topic":"Climate finance","share":0.0565,"seconds":60}],"timeline":[[4,70,"UNGA"],[72,145,"UNGA"],[148,212,"UN leadership"],[215,305,"Lesotho security"],[306,368,"Lesotho climate"],[372,432,"Climate finance"],[434,520,"Lesotho energy"],[521,595,"Technology"],[596,657,"Lesotho economy"],[660,735,"Finance"],[737,800,"Lesotho health"],[801,874,"Migration"],[876,944,"UN reform"],[948,1026,"Conflict zones"],[1029,1097,"Sanctions"],[1098,1130,null]],"stances":{"UNGA":"Samuel Ntsokoane Matekane congratulates the newly elected president of the 81st session and acknowledges their commitment to the multilateral system.","UN leadership":"Samuel Ntsokoane Matekane commends the outgoing Secretary-General's leadership and expresses gratitude for his service.","Lesotho security":"Samuel Ntsokoane Matekane states that Lesotho has restored national peace and security with international support and asserts that preventative diplomacy is the most effective means of avoiding conflict.","Lesotho climate":"Samuel Ntsokoane Matekane states that Lesotho is currently facing severe environmental challenges due to climate change.","Climate finance":"Samuel Ntsokoane Matekane calls for developed countries to honor commitments by providing climate finance and technology transfer to help least developed countries cope with climate change.","Lesotho energy":"The speaker advocates for a just energy transition in Lesotho, highlighting the establishment of a national fund to decarbonize the economy and create employment.","Technology":"Samuel Ntsokoane Matekane supports contributing Lesotho's experience to a proposed global fund for AI capacity building to ensure responsible governance and equitable sharing of artificial intelligence benefits.","Lesotho economy":"Samuel Ntsokoane Matekane states that while Lesotho has accelerated reforms, youth unemployment remains high at 38% and economic diversification is constrained by climate shocks.","Finance":"Samuel Ntsokoane Matekane calls for the reform of the international financial architecture to be more equitable and responsive to developing countries, while urging full implementation of past summit outcomes.","Lesotho health":"Samuel Ntsokoane Matekane calls for enhanced international cooperation and technology sharing to build resilient health systems in Lesotho, citing the development of a new radiotherapy facility.","Migration":"Samuel Ntsokoane Matekane argues that migration benefits all involved countries and must be governed by international cooperation and human rights protections.","UN reform":"Samuel Ntsokoane Matekane calls for UN reforms guided by member state priorities and a stronger voice for African nations in global decision-making.","Conflict zones":"Samuel Ntsokoane Matekane calls for effective diplomatic solutions to secure lasting peace in Ukraine, the Middle East, Sudan, and Eastern DRC, welcomes the ceasefire framework in Gaza, and urges intensified efforts for a speedy resolution in the Gulf conflict.","Sanctions":"Samuel Ntsokoane Matekane calls for the immediate lifting of longstanding sanctions on Cuba and Zimbabwe, arguing they harm innocent civilians."},"claims":[{"t":61,"quote":"Your election reflects the confidence of member states in your steadfast commitment to multilateral system.","topic":"UNGA","kind":"fact"},{"t":102,"quote":"I also pay tribute to your predecessor, her excellency, Miss Babok, president of the 80th session of the general assembly, with whom my delegation had the honor to serve as vice president.","topic":"UNGA","kind":"fact"},{"t":163,"quote":"During his term, the world confronted unprecedented from the coid9 pandemic to the eruption of new conflicts, the catastrophic effects of climate change and unstable uh trade regimes.","topic":"UN leadership","kind":"fact"},{"t":259,"quote":"Leoto has restored national peace and security following successive episodes of political and security unrest with the support of the United Nations, the African Union, Saddak and other friendly nations.","topic":"Lesotho security","kind":"fact"},{"t":276,"quote":"We have reclaimed our rightful place among the community of nations as a stable and peaceful","topic":"Lesotho security","kind":"self_credit"},{"t":356,"quote":"Loto is increasingly experiencing severe floods and droughts resulting in land degradation and extensive damage to critical infrastructure.","topic":"Lesotho climate","kind":"fact"},{"t":372,"quote":"Despite contributing minimally to global greenhouse gas emissions, least developed countries like Loto bear a heavy brand of climate impact.","topic":"Climate finance","kind":"fact"},{"t":384,"quote":"Global warming and rising sea levels pose terrible threats particularly to small islands developing states.","topic":"Climate finance","kind":"fact"},{"t":448,"quote":"Under the visionary leadership of his majesty King Lithia thei, Leo has launched the his majesty king Lithia the third just energy transition fund designed not only to decarbonize our economy but to transform it from one historically reliant on migrant labor to one rooted in renewable energy exports.","topic":"Lesotho energy","kind":"fact"},{"t":510,"quote":"as the first member of state to pilot the UN blueprint for national AI and data strategies from design into national implementation.","topic":"Lesotho energy","kind":"self_credit"},{"t":522,"quote":"Loto stands ready to share the lessons of that journey with fellow developing particularly across Africa and among least developed and landlocked developing countries.","topic":"Technology","kind":"fact"},{"t":575,"quote":"We further stand ready to contribute our experience to emerging instruments such as the proposed global fund for AI capacity building","topic":"Technology","kind":"fact"},{"t":630,"quote":"Youth unemployment stands at 38%","topic":"Lesotho economy","kind":"number"},{"t":673,"quote":"ESRE at the fourth summit for financing for development held in sevil Spain last year.","topic":"Finance","kind":"fact"},{"t":685,"quote":"We also urge full implementation of the outcomes of the third summit of landlocked develop developing countries held in Awasa Tministan in August 2025.","topic":"Finance","kind":"fact"},{"t":737,"quote":"Lutu is undertaking reforms to strengthen our health care system and invite partnerships to ensure universal access to quality primary health medicines, vaccines, diagnostics, and robust disease surveillance and pandemic preparedness.","topic":"Lesotho health","kind":"fact"},{"t":763,"quote":"With support from the international atomic energy agency, Lysoto is developing its first radiotherapy and nuclear medicine facility to provide domestic oncology services.","topic":"Lesotho health","kind":"fact"},{"t":815,"quote":"Migration benefits countries of origin, transit countries and destination countries contributing to skills cultural exchange and shared economic growth.","topic":"Migration","kind":"fact"},{"t":851,"quote":"Protecting their dignity and fundamental freedoms is not only a legal obligation, it is a moral imperative.","topic":"Migration","kind":"fact"},{"t":878,"quote":"reforms must remain guided by intergovernmental agreed mandates and member states priorities","topic":"UN reform","kind":"fact"},{"t":919,"quote":"developing countries, particularly African nations, have a stronger voice in global decision making","topic":"UN reform","kind":"fact"},{"t":988,"quote":"We welcome the ceasefire framework and stabilization arrangement in Gaza","topic":"Conflict zones","kind":"fact"},{"t":998,"quote":"based on the 1967 borders where Israelis and Palestinians coexist in peace and harmony","topic":"Conflict zones","kind":"fact"},{"t":1069,"quote":"my delegation continues to call for the lifting of longstanding sanctions on Cuba and Zimbabwe. These measures deprive innocent civilians of their right to development.","topic":"Sanctions","kind":"fact"}],"promises":[{"t":86,"quote":"my delegation reaffirms its unwavering commitment to working closely with you and all member states to ensure a productive and successful session.","topic":"UNGA","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":4,"topic":"UNGA","text":"The assembly will hear an address by his excellency Samuel and Sukane Matakane, Prime Minister and Minister of Defense and National Security of the Kingdom of I request protocol to escort his excellency and invite him to address the Mr. President, at the outset, allow me to extend my warm and heartfelt congratulations to you on your election as president of the 81st session of the General Assembly. Your election reflects the confidence of member states in your steadfast commitment to multilateral system."},{"t":72,"topic":"UNGA","text":"and we have vision for a United Nations that is responsive, effective, and capable of delivering for As we embark on this important journey, my delegation reaffirms its unwavering commitment to working closely with you and all member states to ensure a productive and successful session. I also pay tribute to your predecessor, her excellency, Miss Babok, president of the 80th session of the general assembly, with whom my delegation had the honor to serve as vice president. Her dedicated skill and tenacity of purpose in strengthening multilateral cooperation during a period of profound global uncertainty gave us hope that the future of this organization can be secured when all nations work together for the common goal of leaving no one behind."},{"t":148,"topic":"UN leadership","text":"To the Secretary General, Mr. Antonio whose tenor is approaching an end. My delegation commends his ex exemplary leadership and commitment to the ideals of the United Nations. During his term, the world confronted unprecedented from the coid9 pandemic to the eruption of new conflicts, the catastrophic effects of climate change and unstable uh trade regimes. Throughout this crisis, he remained the moral force and steady anchor of the We salute him for his distinguished service and will fondly cherish his historic visit to the mountain kingdom in December 2024 during which he witnessed firsthand of the dividends of the UN's contribution to lutu."},{"t":215,"topic":"Lesotho security","text":"Mr. President, the theme for this session, restoring trust, managing a a United Nations that delivers for all resonate deeply with Lutu's aspirations for a more inclusive, transparent, and multilateral system capable of advancing respect for international law, maintaining global peace and security, accelerating sustainable development, protecting human rights, driving climate action, and implementing long overdue institutional reforms. Leoto has restored national peace and security following successive episodes of political and security unrest with the support of the United Nations, the African Union, Saddak and other friendly nations. We have reclaimed our rightful place among the community of nations as a stable and peaceful We therefore attest that preventative diplomacy remains the most effective means of aing conflict and ensuring sustainable peace to create an environment conducive to inclusive growth and development."},{"t":306,"topic":"Lesotho climate","text":"We continue to advance constitutional reforms aimed at strengthening democratic governance and the rule of We remain committed to accountability, professionalism, and respect for human rights for all sectors of society. We recognize that culture of peace requires strong institutions that negate violence in all its forms. an independent judiciary capable of delivering justice impartially and efficiently to restore public trust. Mr. President, we must acknowledge that climate change is no longer a future threat but a present reality. Loto is increasingly experiencing severe floods and droughts resulting in land degradation and extensive damage to critical infrastructure."},{"t":372,"topic":"Climate finance","text":"Despite contributing minimally to global greenhouse gas emissions, least developed countries like Loto bear a heavy brand of climate impact. Global warming and rising sea levels pose terrible threats particularly to small islands developing states. We stand in solidarity with these nations and call for greater global to cope with these climate related challenges. We call upon developed countries to honor their commitments by providing new adequate, predictable and accessible climate finance. Further, we urge developed countries to transfer environmentally sound technology and to strengthen capacity of developing countries to effectively mitigate and adapt to the adverse effects of climate change."},{"t":434,"topic":"Lesotho energy","text":"Climate justice demands nothing less. Just energy transition is therefore an imperative if humanity is to be spared from the terrible threat of climate change. Under the visionary leadership of his majesty King Lithia thei, Leo has launched the his majesty king Lithia the third just energy transition fund designed not only to decarbonize our economy but to transform it from one historically reliant on migrant labor to one rooted in renewable energy exports. The fund seeks to attract investment to build new energy generation capacity, unlock energy independence and lay a new foundation for national prosperity that benefits every Mosu. We therefore we therefore call for partnerships to mobilize the requisite resources for clean energy project which can create significant employment opportunities for our youth and women as the first member of state to pilot the UN blueprint for national AI and data strategies from design into national implementation."},{"t":521,"topic":"Technology","text":"ation. Loto stands ready to share the lessons of that journey with fellow developing particularly across Africa and among least developed and landlocked developing countries. Chatting similar paths towards digital Central to that experience has been the value of the United Nations system acting as one coordinated around priorities that we ourselves defined rather than delivered through separate and uncoordinated channels. This is what the United Nations that delivers for all looks like in practice and we commend this model to the organization as it advances the UN8 initiative. We further stand ready to contribute our experience to emerging instruments such as the proposed global fund for AI capacity building so that the compromise of artificial intelligence may be governed responsibly and shared equitably among all nations."},{"t":596,"topic":"Lesotho economy","text":"We are grateful for the UN's continued support in this digital transformation Mr. President, the Kingdom of Loto remains committed to the 2030 agenda. We have accelerated reforms in business trade facilitation, public financial management, youth empowerment, and renewable energy. Yet, challenges persist. Economic diversification remains Youth unemployment stands at 38%. And climate related shocks and equality continue to constrain inclusive With only three years remaining until 2030, we appeal to the international community to honor their official development assistance commitments which is which is an essential step in restoring trust."},{"t":660,"topic":"Finance","text":"We further call for reform of the international financial architecture to make it more equitable, fit for purpose and responsive to the needs of developing countries. ESRE at the fourth summit for financing for development held in sevil Spain last year. We also urge full implementation of the outcomes of the third summit of landlocked develop developing countries held in Awasa Tministan in August 2025. The implementation of these outcomes without further delay together with the pact of the future will undoubtedly help restore eroded trust. Mr. President, universal health coverage remains central to our development agenda. While investment have been made, we continue to face serious public health challenges including a high burden of communicable and non-communic non-committable disease and equalities in access to health."},{"t":737,"topic":"Lesotho health","text":"Lutu is undertaking reforms to strengthen our health care system and invite partnerships to ensure universal access to quality primary health medicines, vaccines, diagnostics, and robust disease surveillance and pandemic preparedness. The social and economic cost of cancer are profound. With support from the international atomic energy agency, Lysoto is developing its first radiotherapy and nuclear medicine facility to provide domestic oncology services. We therefore call for enhanced cooperation in technology sharing, capacity building, and sustainable health financing to build resilient health systems capable of responding to current and emerging challenges. Mr. President, migration is not an abstract concept for the people of Lutu."},{"t":801,"topic":"Migration","text":"It is a daily lift reality. It is woven into our social fabric as human ambition rooted dignity, opportunity and aspiration. Migration benefits countries of origin, transit countries and destination countries contributing to skills cultural exchange and shared economic growth. We must therefore strengthen international cooperation to ensure migration contributes meaningfully to deeper human understanding and sustainable development. Guided by the universal declaration of human rights, we must guarantee the full of human rights by migrants regardless of status. Protecting their dignity and fundamental freedoms is not only a legal obligation, it is a moral imperative. Mr. President, we welcome progress under the UN8 initiative and appreciate efforts to enhance efficiency, and coherence within the UN system."},{"t":876,"topic":"UN reform","text":"As the liberations continue, reforms must remain guided by intergovernmental agreed mandates and member states priorities. Any missions undertaken should preserve the UN's capacity to deliver across all pillars of its work and maintain meaningful impact on the ground. Mr. President, as we contemplate the future of Community of Nations, we must renew our collective commitment to a United Nations that is more inclusive, and responsive to modern times global challenges and one in which developing countries, particularly African nations, have a stronger voice in global decision making. We reiterate our support for comprehensive reform of the security in line with the Sulini consul to make it more representative, equitable and reflective of our current geopolitical realities."},{"t":948,"topic":"Conflict zones","text":"The Kingdom of Loto reaffirms its unwavering commitment to the charter of the United Nations. Multilateral system and the rule of law, international law remains the cornerstone of sovereign equality. Peace coexist existence and sustainable Mr. President, the rise in regional conflicts is cause for deep concern. We call for effective diplomatic solutions to secure lasting peace in Ukraine, the Middle East, Sudan, and Eastern DRC. We welcome the ceasefire framework and stabilization arrangement in Gaza and call for sustained engagement to achieve a lasting solution based on the 1967 borders where Israelis and Palestinians coexist in peace and harmony. Regarding the broader conflict in the Gulf, we urge all parties to intensify efforts towards a speedy resolution as its economic impact is dire and devastating for humanity cannot continue to bear the high cost of these wars."},{"t":1029,"topic":"Sanctions","text":"We should draw inspiration from the wisdom of Chief Muslim, one of our renowned diplomats who advised Morana Musha the first, the founding father of the Vasuti nation. That it is better to thrash corn than sharpen the spear. As the United Nation, we must continue investing in conflict prevention and building strong democract democratic institutions grounded in good governance, peace, and respect for international law. Mr. President, my delegation continues to call for the lifting of longstanding sanctions on Cuba and Zimbabwe. These measures deprive innocent civilians of their right to development. In conclusion, Loto firmly believes that cooperation, solidarity, and shared responsibility are the only viable path towards a peaceful, prosperous, and sustainable future."},{"t":1098,"topic":null,"text":"Let us recommmit ourselves to a multilateral system that delivers tangible results for humanity, protects our planet, promote peace and international security and ensures that no one is left behind. I thank you. On behalf of the assembly, I wish to thank the Prime Minister and Minister of Defense and National Security of the Kingdom of Lutu."}],"compare":[{"topic":"UN & its reform","share":0.2563,"mean":0.2045,"rank":64,"others":170},{"topic":"Lesotho","share":0.0847,"mean":0.0,"rank":1,"others":0},{"topic":"Regional Security","share":0.0731,"mean":0.0043,"rank":4,"others":12},{"topic":"Global Economy","share":0.071,"mean":0.0143,"rank":20,"others":31},{"topic":"Artificial Intelligence","share":0.0697,"mean":0.0504,"rank":59,"others":83},{"topic":"Migration","share":0.0681,"mean":0.0045,"rank":9,"others":12},{"topic":"Sanctions","share":0.0639,"mean":0.0028,"rank":5,"others":5},{"topic":"Climate Change","share":0.0565,"mean":0.0427,"rank":60,"others":77}]};
